// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport android.app.NotificationManagerimport android.content.Contextimport android.os.PowerManagerimport com.roshan.persona.brain.skill.DndMode/** * NOUS — DnD + Battery Saver Services (Module 10 v2 — Step 10.9). * * Thin service interfaces for Do Not Disturb + Battery Saver, wrapping * [NotificationManager] and [PowerManager] for handler testability. */// ──────────────────────────────────────────────────────────────────────────// DnD service// ──────────────────────────────────────────────────────────────────────────/** * Wraps `NotificationManager.setInterruptionFilter` for [DnDHandler]. */interface DnDService {    /** Get the current DnD mode. */    fun getMode(): DndMode    /**     * Set the DnD mode.     *     * @return true on success, false on failure (e.g., no DnD access).     */    fun setMode(mode: DndMode): Boolean    /** True if the app has DnD access (ACCESS_NOTIFICATION_POLICY granted). */    fun hasDndAccess(): Boolean}/** * Android [DnDService] backed by [NotificationManager]. */class AndroidDnDService(    private val notificationManager: NotificationManager,) : DnDService {    override fun getMode(): DndMode = try {        when (notificationManager.currentInterruptionFilter) {            NotificationManager.INTERRUPTION_FILTER_NONE -> DndMode.NONE            NotificationManager.INTERRUPTION_FILTER_PRIORITY -> DndMode.PRIORITY            NotificationManager.INTERRUPTION_FILTER_ALARMS -> DndMode.ALARMS            else -> DndMode.ALL        }    } catch (t: Throwable) {        Timber.tag("AndroidDnDService").w("getMode failed", t)        DndMode.ALL    }    override fun setMode(mode: DndMode): Boolean = try {        val filter = when (mode) {            DndMode.NONE -> NotificationManager.INTERRUPTION_FILTER_NONE            DndMode.PRIORITY -> NotificationManager.INTERRUPTION_FILTER_PRIORITY            DndMode.ALARMS -> NotificationManager.INTERRUPTION_FILTER_ALARMS            DndMode.ALL -> NotificationManager.INTERRUPTION_FILTER_ALL        }        notificationManager.setInterruptionFilter(filter)        true    } catch (e: SecurityException) {        Timber.tag("AndroidDnDService").w("ACCESS_NOTIFICATION_POLICY not granted", e)        false    } catch (t: Throwable) {        Timber.tag("AndroidDnDService").w("setMode failed", t)        false    }    override fun hasDndAccess(): Boolean = try {        notificationManager.isNotificationPolicyAccessGranted    } catch (t: Throwable) {        false    }}// ──────────────────────────────────────────────────────────────────────────// Battery saver service// ──────────────────────────────────────────────────────────────────────────/** * Wraps `PowerManager.setPowerSaveMode` for [BatterySaverHandler]. */interface BatterySaverService {    /** True if battery saver is currently on. */    fun isOn(): Boolean    /**     * Toggle battery saver on/off.     *     * @return true on success.     */    fun setOn(on: Boolean): Boolean}/** * Android [BatterySaverService] backed by [PowerManager]. */class AndroidBatterySaverService(    private val powerManager: PowerManager,) : BatterySaverService {    override fun isOn(): Boolean = try {        powerManager.isPowerSaveMode    } catch (t: Throwable) {        false    }    override fun setOn(on: Boolean): Boolean = try {        // PowerManager.setPowerSaveMode is a hidden API on some OEM ROMs.        // Use reflection for maximum compatibility.        val method = powerManager.javaClass.getMethod("setPowerSaveMode", Boolean::class.javaPrimitiveType)        method.invoke(powerManager, on) as? Boolean ?: false        true    } catch (t: Throwable) {        Timber.tag("AndroidBatterySaverService").w("setOn failed", t)        false    }}